create or replace function public.gmp_check_camera_scope() returns trigger language plpgsql security invoker set search_path=public as $$ declare store_branch uuid; begin if new.store_id is not null then if not exists(select 1 from public.gmp_stores s where s.id=new.store_id and s.organization_id=new.organization_id) then raise exception 'camera_store_organization_mismatch'; end if; select branch_id into store_branch from public.gmp_stores where id=new.store_id; if new.branch_id is not null and store_branch is not null and new.branch_id<>store_branch then raise exception 'camera_store_branch_mismatch'; end if; end if; if new.branch_id is not null and not exists(select 1 from public.gmp_branches b where b.id=new.branch_id and b.organization_id=new.organization_id) then raise exception 'camera_branch_organization_mismatch'; end if; return new; end $$;
drop trigger if exists gmp_cameras_scope_check on public.gmp_cameras; create trigger gmp_cameras_scope_check before insert or update on public.gmp_cameras for each row execute function public.gmp_check_camera_scope();
create or replace function public.gmp_check_compliance_case_transition() returns trigger language plpgsql security invoker set search_path=public as $$ begin if new.status=old.status then return new; end if; if not ( (old.status='open' and new.status in ('under_review','closed','failed')) or (old.status='under_review' and new.status in ('submitted','closed','failed')) or (old.status='submitted' and new.status in ('accepted','rejected','failed')) or (old.status='failed' and new.status in ('under_review','closed')) ) then raise exception 'invalid_compliance_case_transition: % -> %',old.status,new.status; end if; return new; end $$;
drop trigger if exists gmp_compliance_case_transition_check on public.gmp_compliance_cases; create trigger gmp_compliance_case_transition_check before update of status on public.gmp_compliance_cases for each row execute function public.gmp_check_compliance_case_transition();
create or replace function public.gmp_check_einvoice_transition() returns trigger language plpgsql security invoker set search_path=public as $$ begin if new.status=old.status then return new; end if; if not ( (old.status='queued' and new.status in ('sending','cancelled','failed')) or (old.status='sending' and new.status in ('submitted','accepted','rejected','failed')) or (old.status='submitted' and new.status in ('accepted','rejected','failed')) or (old.status='failed' and new.status in ('queued','cancelled')) ) then raise exception 'invalid_einvoice_submission_transition: % -> %',old.status,new.status; end if; return new; end $$;
drop trigger if exists gmp_einvoice_transition_check on public.gmp_einvoice_submissions; create trigger gmp_einvoice_transition_check before update of status on public.gmp_einvoice_submissions for each row execute function public.gmp_check_einvoice_transition();